document.getElementById('adminLoginForm').addEventListener('submit', (e) => {
  e.preventDefault();
  const email = document.getElementById('email').value.trim();
  const password = document.getElementById('password').value;
  const result = FS.login({ email, password });
  const errEl = document.getElementById('formError');
  if (!result.ok) {
    errEl.textContent = result.error;
    errEl.classList.add('show');
    return;
  }
  if (result.user.role !== 'admin') {
    errEl.textContent = 'This account is not an administrator account.';
    errEl.classList.add('show');
    FS.logout();
    return;
  }
  errEl.classList.remove('show');
  fsToast('Logged in — welcome back!', 'success');
  setTimeout(() => { window.location.href = FS.dashboardFor(result.user.role); }, 400);
});

document.getElementById('password').addEventListener('input', (e) => {
  fsRenderPasswordStrength(e.target.value, document.getElementById('strengthMeter'));
});

document.getElementById('adminSignupForm').addEventListener('submit', (e) => {
  e.preventDefault();
  const name = document.getElementById('name').value.trim();
  const email = document.getElementById('email').value.trim();
  const phone = document.getElementById('phone').value.trim();
  const password = document.getElementById('password').value;

  let valid = true;
  fsSetFieldError('name', 'nameError', !name); if (!name) valid = false;
  const emailOk = fsIsValidEmail(email);
  fsSetFieldError('email', 'emailError', !emailOk); if (!emailOk) valid = false;
  const phoneOk = fsIsValidPhone(phone);
  fsSetFieldError('phone', 'phoneError', !phoneOk); if (!phoneOk) valid = false;
  const passwordOk = password.length >= 6;
  fsSetFieldError('password', 'passwordError', !passwordOk); if (!passwordOk) valid = false;

  const formError = document.getElementById('formError');
  formError.classList.remove('show');
  if (!valid) return;

  const result = FS.signup({ role: 'admin', name, email, password, phone, address: 'FoodShare HQ' });
  if (!result.ok) {
    formError.textContent = result.error;
    formError.classList.add('show');
    return;
  }
  fsToast('Admin account created — welcome, ' + result.user.name + '!', 'success');
  setTimeout(() => { window.location.href = FS.dashboardFor('admin'); }, 500);
});

document.getElementById('contactForm').addEventListener('submit', function (e) {
  e.preventDefault();

  const fields = [
    { id: 'cName', errorId: 'cNameError', test: v => v.trim().length > 0 },
    { id: 'cEmail', errorId: 'cEmailError', test: v => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()) },
    { id: 'cSubject', errorId: 'cSubjectError', test: v => v.trim().length > 0 },
    { id: 'cMessage', errorId: 'cMessageError', test: v => v.trim().length > 4 },
  ];

  let valid = true;
  fields.forEach(f => {
    const el = document.getElementById(f.id);
    const errEl = document.getElementById(f.errorId);
    const ok = f.test(el.value);
    el.classList.toggle('input-error', !ok);
    errEl.classList.toggle('show', !ok);
    if (!ok) valid = false;
  });

  if (!valid) return;

  fsToast('Message sent — we\'ll be in touch soon.', 'success');
  this.reset();
  fields.forEach(f => {
    document.getElementById(f.id).classList.remove('input-error');
    document.getElementById(f.errorId).classList.remove('show');
  });
});

// If we arrived from a role-specific login page (?role=admin / ?role=volunteer),
// send "Back to login" back to the right place instead of the generic login page.
const role = new URLSearchParams(window.location.search).get('role');
const loginPage = role === 'admin' ? 'admin-login.html' : role === 'volunteer' ? 'volunteer-login.html' : 'login.html';
document.getElementById('backToLoginTop').setAttribute('href', loginPage);

document.getElementById('forgotForm').addEventListener('submit', (e) => {
  e.preventDefault();
  const email = document.getElementById('email').value.trim();
  const emailOk = fsIsValidEmail(email);
  fsSetFieldError('email', 'emailError', !emailOk);
  if (!emailOk) return;

  const result = FS.requestPasswordReset(email);

  document.getElementById('forgotForm').style.display = 'none';
  document.getElementById('resultArea').style.display = 'block';

  const linkBox = document.getElementById('linkBox');
  if (result.token) {
    const url = new URL('reset-password.html', window.location.href);
    url.searchParams.set('token', result.token);
    document.getElementById('demoLinkInput').value = url.toString();
    document.getElementById('openLinkBtn').setAttribute('href', url.toString());
    linkBox.style.display = 'block';
  } else {
    // No matching account — intentionally identical message shown above,
    // so we simply don't reveal a link. This avoids leaking which emails
    // are registered.
    linkBox.style.display = 'none';
  }
});

document.getElementById('copyLinkBtn').addEventListener('click', () => {
  const input = document.getElementById('demoLinkInput');
  input.select();
  navigator.clipboard?.writeText(input.value).then(() => fsToast('Link copied to clipboard.', 'success'))
    .catch(() => fsToast('Could not copy — select and copy manually.', 'error'));
});

document.addEventListener('DOMContentLoaded', () => {
  const donations = FS.getDonations();
  const completed = donations.filter(d => d.status === 'completed');
  const available = FS.getAvailableDonations();
  const mealsRescued = completed.reduce((sum, d) => sum + FS.estimateMeals(d), 0) + available.reduce((sum, d) => sum + FS.estimateMeals(d), 0);
  const ngoCount = new Set(donations.filter(d => d.ngoId).map(d => d.ngoId)).size;

  document.getElementById('heroStats').innerHTML = `
    <div><div class="mono" style="font-size:1.6rem;font-weight:700;color:var(--leaf-700);">${available.length}</div><div style="font-size:0.82rem;color:var(--text-muted);">Available now</div></div>
    <div><div class="mono" style="font-size:1.6rem;font-weight:700;color:var(--leaf-700);">${mealsRescued}</div><div style="font-size:0.82rem;color:var(--text-muted);">Meals rescued</div></div>
    <div><div class="mono" style="font-size:1.6rem;font-weight:700;color:var(--leaf-700);">${ngoCount}</div><div style="font-size:0.82rem;color:var(--text-muted);">NGO partners</div></div>
  `;

  const soonest = available[0];
  document.getElementById('heroDonation').innerHTML = soonest ? `
    <div style="display:flex; gap:1rem; align-items:flex-start; margin-top:0.75rem;">
      ${fsStampHTML(soonest.expiryTime).replace('var(--surface)', 'var(--leaf-900)')}
      <div>
        <div style="font-family:var(--font-display); font-size:1.15rem;">${fsEscape(soonest.foodName)}</div>
        <div style="color:var(--leaf-300); font-size:0.85rem; margin-top:0.25rem;">${fsEscape(soonest.quantity)} ${fsEscape(soonest.unit)} · ${fsEscape(soonest.category)}</div>
        <div style="color:var(--leaf-300); font-size:0.8rem; margin-top:0.5rem;">Posted by ${fsEscape(soonest.donorName)}</div>
      </div>
    </div>
  ` : `<p style="color:var(--leaf-300); margin-top:0.75rem;">No surplus posted yet — be the first.</p>`;

  const board = document.getElementById('liveBoard');
  if (!available.length) {
    board.innerHTML = `<div class="empty-state" style="grid-column:1/-1;"><h3>Nothing on the board yet</h3><p>Once a donor posts surplus food, it will appear here.</p></div>`;
  } else {
    board.innerHTML = available.slice(0, 3).map(d => `
      <div class="donation-card">
        <div class="donation-card-top">
          <div><h3>${fsEscape(d.foodName)}</h3><div class="donation-meta"><span>${fsEscape(d.category)}</span></div></div>
          ${fsStampHTML(d.expiryTime)}
        </div>
        <p style="color:var(--text-muted); margin:0; font-size:0.9rem;">${fsEscape(d.description || 'No extra notes from the donor.')}</p>
        <div class="donation-card-foot">
          <span class="mono" style="font-size:0.85rem;">${fsEscape(d.quantity)} ${fsEscape(d.unit)}</span>
          ${fsBadgeHTML(d.status)}
        </div>
      </div>
    `).join('');
  }
});

