const token = new URLSearchParams(window.location.search).get('token');
const check = token ? FS.verifyResetToken(token) : { ok: false, error: 'No reset token was provided.' };

if (!check.ok) {
  document.getElementById('invalidMessage').textContent = check.error;
  document.getElementById('invalidState').style.display = 'block';
} else {
  document.getElementById('formState').style.display = 'block';
  document.getElementById('targetEmail').textContent = check.user.email;

  document.getElementById('password').addEventListener('input', (e) => {
    fsRenderPasswordStrength(e.target.value, document.getElementById('strengthMeter'));
  });

  document.getElementById('resetForm').addEventListener('submit', (e) => {
    e.preventDefault();
    const password = document.getElementById('password').value;
    const confirmPassword = document.getElementById('confirmPassword').value;

    let valid = true;
    const passwordOk = password.length >= 6;
    fsSetFieldError('password', 'passwordError', !passwordOk); if (!passwordOk) valid = false;
    const matchOk = password === confirmPassword && confirmPassword.length > 0;
    fsSetFieldError('confirmPassword', 'confirmError', !matchOk); if (!matchOk) valid = false;

    const formError = document.getElementById('formError');
    formError.classList.remove('show');
    if (!valid) return;

    const result = FS.resetPassword(token, password);
    if (!result.ok) {
      formError.textContent = result.error;
      formError.classList.add('show');
      return;
    }
    fsToast('Password updated — you can log in now.', 'success');
    const dest = { admin: 'admin-login.html', volunteer: 'volunteer-login.html' }[result.user.role] || 'login.html';
    setTimeout(() => { window.location.href = dest; }, 700);
  });
}

